mapper.select:
SELECT p.*, d.dept_name AS deptName FROM post p LEFT JOIN dept d ON p.dept_id = d.id
AND p.dept_id = #{deptId}
AND p.post_name LIKE CONCAT('%', #{postName}, '%')

mapper.update:
update post
set post_name=#{postName},
    dept_id=#{deptId},
    base_salary=#{baseSalary}
where id=#{id}
